import{_ as t,o,c as s,ah as d}from"./chunks/framework.ojwJKwrc.js";const u=JSON.parse('{"title":"Heliodor マクロベンチマーク","description":"","frontmatter":{},"headers":[],"relativePath":"ja/benchmarks/heliodor.md","filePath":"ja/benchmarks/heliodor.md"}'),a={name:"ja/benchmarks/heliodor.md"};function c(i,e,l,r,n,p){return o(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="heliodor-マクロベンチマーク" tabindex="-1">Heliodor マクロベンチマーク <a class="header-anchor" href="#heliodor-マクロベンチマーク" aria-label="Permalink to &quot;Heliodor マクロベンチマーク&quot;">​</a></h1><p>Heliodor は Veryl で書かれた大規模な RISC-V プロセッサで、Linux boot の ignored test を持っています。プロジェクト読み込み、<code>$readmemh</code> による大きなメモリ初期化、native testbench scheduling、長時間の順序回路シミュレーションをまとめて踏むので、Celox を Veryl native simulator として見るためのマクロベンチに向いています。</p><p>ベンチマーク実行ファイルはworkspaceの<code>celox-bench</code> crateが所有します。 これらは公開<code>celox</code> APIのexampleではありません。<code>celox-heliodor</code>がCeloxの 計測対象、<code>veryl-heliodor</code>が同期Veryl referenceです。shell driverは固定された 外部入力を準備し、これらを実行してmachine-readableな終了recordを検証します。</p><p>専用の Heliodor CI workflow は Heliodor を <code>target/heliodor/source</code> に checkout し、計測前に時間分離版 Veryl runner と Celox runner を build します。デフォルトでは Veryl baseline を先に測ってから Celox を走らせ、TSV サマリとフルログを <code>target/heliodor/results</code> に出します。</p><h2 id="実行" tabindex="-1">実行 <a class="header-anchor" href="#実行" aria-label="Permalink to &quot;実行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p><code>run</code> は構成を変更できる診断用コマンドです。測定値を追記しますが、Celox が性能要件を満たすかは判定しません。その判定には固定構成の <code>gate</code> を使います。</p><p>デフォルトでは <code>test_soc_linux_boot</code> を同期 Veryl AOT-C、Celox の順に走らせます。 Celox はその test で成功した Veryl baseline の <code>HELIODOR_CELOX_TIMEOUT_MULTIPLIER</code> 倍で timeout します。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_TESTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test_soc_linux_boot test_soc_smp_linux_boot_2hart&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;celox veryl-cranelift veryl-cc&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scripts/run-heliodor-bench.sh </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run</span></span></code></pre></div><p><code>HELIODOR_REF</code> を指定しない限り、Heliodor は commit <code>7ad830fc0f8506c934b61a853ce2eadfa5926b82</code> に固定します。</p><h2 id="コード生成時間と実行時間の分離" tabindex="-1">コード生成時間と実行時間の分離 <a class="header-anchor" href="#コード生成時間と実行時間の分離" aria-label="Permalink to &quot;コード生成時間と実行時間の分離&quot;">​</a></h2><p>デフォルトの同期 Veryl-CC runner は、生成コードの throughput と compiler latency を分離します。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;veryl-cc-sync celox&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_TIMEOUT_SEC=300 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scripts/run-heliodor-bench.sh </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run</span></span></code></pre></div><p>両 runner は build/prepare と testbench 実行を別々に報告します。Celox はさらに、 生成native関数内で消費したwall timeを<code>jit_execute_elapsed_ns</code>として報告します。 時計を読むのはsimulated tickごとではなくhost側native batchごとです。 <code>execute_elapsed_ns</code>はその外側の区間であり、testbench schedulingとruntime event処理も 含みます。compile 区間には frontend 解析、最適化、native コード生成、Simulator 初期化、initial testbench lowering を含み、構築済みtestbenchを実行する直前で終了します。 Veryl 側は Veryl 0.20.2 の Heliodor benchmark と同じ同期 AOT-C 設定 （<code>aot_c_async=false</code>）を使うため、コード生成完了後に実行が始まります。 これにより、入力依存の Cranelift から C への hot-swap 時点を実行時間に混ぜません。 各 Veryl-CC 実行には新しい空の一時 AOT cache を割り当てるため、共有 cache の <code>.so</code> hit をコード生成時間として誤計測しません。source 読み込みと process 起動は 両内部区間の外で、<code>process_elapsed_ns</code> にだけ含まれます。</p><p>最初の非 LTO 分離測定は、両者とも正確な <code>cy=9ae070 x3=aa pass=1</code> で完了しました。</p><table tabindex="0"><thead><tr><th>Runner</th><th style="text-align:right;">コード生成</th><th style="text-align:right;">実行</th></tr></thead><tbody><tr><td><code>veryl-cc-sync</code></td><td style="text-align:right;">58.354 s</td><td style="text-align:right;">54.282 s</td></tr><tr><td><code>celox</code></td><td style="text-align:right;">40.450 s</td><td style="text-align:right;">137.675 s</td></tr></tbody></table><p>したがって現時点の生成コード実行差は <code>2.536x</code> です。この測定では Celox の cold compile 区間は Veryl の <code>0.693x</code> でした。従来の固定 gate の <code>2.605x</code> は end-to-end process 比であり、実行だけの比ではありません。native 実行最適化の 採否には <code>execute_elapsed_ns</code>、compiler latency には <code>compile_elapsed_ns</code> を 使います。この記録は <code>target/heliodor/results/split_timing_aligned_20260716T021500Z</code> にあります。</p><h2 id="acceptance-gate" tabindex="-1">Acceptance gate <a class="header-anchor" href="#acceptance-gate" aria-label="Permalink to &quot;Acceptance gate&quot;">​</a></h2><p>clean かつ commit 済みの Celox checkout から、再現可能な throughput 比較を 実行します。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gate</span></span></code></pre></div><p>gate の構成は変更できません。以下をすべて固定します。</p><ul><li>公式 repository の Heliodor commit <code>7ad830fc0f8506c934b61a853ce2eadfa5926b82</code> と clean な checkout</li><li>clean な Celox <code>Cargo.lock</code> と locked build で固定した Veryl simulator <code>0.20.2</code>。<code>PATH</code> や <code>VERYL_BIN</code> の CLI は使わない</li><li>clean で途中に変化しない Celox <code>HEAD</code>。invocation ごとの空の Cargo target directory に時間分離版 Veryl と Celox の locked release/LTO build を行い、 その成果物を実行</li><li><code>test_soc_linux_boot</code>、runner 順序 <code>veryl-cc-sync</code>、<code>celox</code>、各 420 秒 timeout</li><li>invocation ごとに新しい空の Veryl AOT cache を作り、実行後に削除</li><li>Celox native backend、<code>O2</code>、2-state、full execution、SIR pass override なし</li><li>runner ごとに別の detached Heliodor worktree。project-local な生成物を runner 間で共有しない</li></ul><p>gate は <code>target/heliodor/results</code> の下に、新しい独立した <code>gate_&lt;timestamp&gt;.&lt;suffix&gt;</code> directory を作ります。その invocation が生成した 2 行だけを受理します。両 runner は正常終了し、正確な config 行、分離 timing 行、 full-pass result 行をそれぞれちょうど 1 件報告する必要があります。Celox は native/O2/<code>four_state=false</code>/<code>compile_only=false</code>、Veryl は同期 AOT-C の <code>aot_c_async=false</code> でなければなりません。実行前後で source manifest、 checkout identity、runner executable hash も検査します。 さらに両ログに architectural completion marker がちょうど 1 件あり、 16 進数の先頭 0 を除いて <code>cy=9ae070 x3=aa pass=1</code> と一致することを要求します。</p><p>両 runner は Simulator と initial testbench の構築完了までを <code>compile_elapsed_ns</code>、構築済みtestbenchの実行を <code>execute_elapsed_ns</code> として 測ります。Celoxは生成native関数の呼出しだけを<code>jit_execute_elapsed_ns</code>にも集計します。 両方の semantic check が成功し、Celox のJIT実行区間が Veryl の実行区間以下の場合に だけ gate は 0 で終了します。Celoxの外側の実行区間とコード生成 latency は別に記録・表示し、実行 throughput の判定には混ぜません。subprocess 時間は end-to-end の診断値です。 compile-only、partial window、または正確な marker を伴わない process exit 0 は 失敗です。<code>--kill-after</code> を持つ GNU <code>timeout</code> と Python 3 が必要です。</p><p>時間分離前の直近の反復用非 LTO 比較では、同じ <code>cy=9ae070</code> の workload が Veryl-CC で <code>76.446 s</code>、Celox で <code>184.652 s</code> でした。その後、clean な Celox commit <code>e917489e</code> から fresh な locked release/LTO runner を build して固定 gate を実行しました。Veryl-CC は <code>68.409 s</code>、Celox は process 時間 <code>178.223 s</code> （runner 内部報告 <code>178.019 s</code>）でした。両者の semantic check は成功し、両ログに <code>cy=9ae070 x3=aa pass=1</code> がちょうど 1 件ありましたが、Celox は <code>2.605x</code> 遅いため、当時の合計process時間による性能条件に失敗しました。成果物は <code>target/heliodor/results/gate_20260716T010312Z.tcVUZd</code> にあります。通常の開発反復 では引き続き非 LTO の <code>heliodor-dev</code> profile を使います。分離後の固定 gate は、 実装をcommitし、意図した最終release/LTO qualificationを行う段階でだけ実行します。</p><h2 id="テスト" tabindex="-1">テスト <a class="header-anchor" href="#テスト" aria-label="Permalink to &quot;テスト&quot;">​</a></h2><p>Heliodor の <code>#[test]</code> module 一覧は以下で見られます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>主な長時間テスト:</p><table tabindex="0"><thead><tr><th>Test</th><th>意味</th></tr></thead><tbody><tr><td><code>test_soc_linux_boot</code></td><td>Linux 5.15 single-hart boot</td></tr><tr><td><code>test_soc_smp_linux_boot_2hart</code></td><td>Linux 5.15 SMP 2-hart boot</td></tr><tr><td><code>test_soc_smp_linux_boot_4hart</code></td><td>Linux 5.15 SMP 4-hart boot</td></tr><tr><td><code>test_soc_linux_boot_71</code></td><td>Linux 7.1 single-hart boot</td></tr><tr><td><code>test_soc_smp_linux_boot_71_2hart</code></td><td>Linux 7.1 SMP 2-hart boot</td></tr><tr><td><code>test_soc_linux_boot_71v</code></td><td>Linux 7.1 vector-enabled boot</td></tr></tbody></table><h2 id="ランナー" tabindex="-1">ランナー <a class="header-anchor" href="#ランナー" aria-label="Permalink to &quot;ランナー&quot;">​</a></h2><p><code>HELIODOR_RUNNERS</code> には以下を指定できます。</p><table tabindex="0"><thead><tr><th>Runner</th><th>Command</th></tr></thead><tbody><tr><td><code>celox</code></td><td><code>target/&lt;profile&gt;/celox-heliodor --project ... --test ...</code></td></tr><tr><td><code>veryl-cc-sync</code></td><td>分離計測を行う Veryl 0.20.2 同期 AOT-C runner</td></tr><tr><td><code>veryl-cc</code></td><td><code>veryl test --ignored --test ... --backend cc</code></td></tr><tr><td><code>veryl-cranelift</code></td><td><code>veryl test --ignored --test ... --backend cranelift</code></td></tr><tr><td><code>veryl-interpret</code></td><td><code>veryl test --ignored --test ... --backend interpret</code></td></tr></tbody></table><p>Celox runner は Celox の default backend を使います。x86-64 host では native x86-64 backend です。最適化プリセットは <code>CELOX_OPT_LEVEL=O0|O1|O2</code> で変えられます。</p><p>全 runner/test の timeout を固定したい場合は <code>HELIODOR_TIMEOUT_SEC</code> を指定します。Veryl baseline がまだない場合、Linux boot は single-hart 300 秒、2-hart SMP 600 秒、4-hart SMP 1800 秒などの固定 fallback を使います。</p><p><code>veryl</code> が <code>PATH</code> に無い場合、スクリプトは <code>cargo install veryl --version 0.20.2 --locked</code> を <code>target/heliodor/tools/veryl-0.20.2</code> に実行します。<code>VERYL_BIN</code>、<code>HELIODOR_VERYL_VERSION</code> で上書きできます。自動インストールを止める場合は <code>HELIODOR_INSTALL_TOOLS=0</code> を指定します。</p><h2 id="結果の意味" tabindex="-1">結果の意味 <a class="header-anchor" href="#結果の意味" aria-label="Permalink to &quot;結果の意味&quot;">​</a></h2><p><code>target/heliodor/results/results.tsv</code> は subprocess の終了 status と、 シミュレーションした test の意味上の結果を区別します。列は以下です。</p><table tabindex="0"><thead><tr><th>列</th><th>意味</th></tr></thead><tbody><tr><td><code>runner</code></td><td>runner 名</td></tr><tr><td><code>test</code></td><td>指定した Heliodor test</td></tr><tr><td><code>status</code></td><td>既存 reader のため第 3 列に残す <code>exit_status</code> の旧名</td></tr><tr><td><code>elapsed_ns</code></td><td>full pass の wall time。full pass 以外は必ず <code>NA</code></td></tr><tr><td><code>log</code></td><td>runner の完全な log</td></tr><tr><td><code>semantic_status</code></td><td><code>pass</code>、<code>fail</code>、<code>compile-only</code>、<code>unreported</code>、<code>invalid</code></td></tr><tr><td><code>exit_status</code></td><td>subprocess の終了 status</td></tr><tr><td><code>process_elapsed_ns</code></td><td>fail や compile-only を含む subprocess の monotonic elapsed time</td></tr><tr><td><code>reported_elapsed_ns</code></td><td>runner 内部の総 elapsed。取得できない場合は <code>NA</code></td></tr><tr><td><code>compile_elapsed_ns</code></td><td>Simulator・testbench 構築までを含む build/prepare 内部時間。取得できない場合は <code>NA</code></td></tr><tr><td><code>execute_elapsed_ns</code></td><td>コード生成完了後の testbench 実行時間。取得できない場合は <code>NA</code></td></tr><tr><td><code>jit_execute_elapsed_ns</code></td><td>Celox生成native関数内の実行時間。未対応backend/runnerは<code>NA</code></td></tr></tbody></table><p>従来の <code>runner</code>、<code>test</code>、<code>status</code>、<code>elapsed_ns</code>、<code>log</code> は同じ順序で 残ります。end-to-end process 結果として扱えるのは <code>semantic_status=pass</code>、 <code>exit_status=0</code> かつ <code>elapsed_ns</code> が数値の行だけです。この旧列は生成コードの 実行性能ではありません。生成コード品質には<code>jit_execute_elapsed_ns</code>、コード生成後の simulator全体には<code>execute_elapsed_ns</code>、compiler latencyには <code>compile_elapsed_ns</code> を使います。<code>process_elapsed_ns</code> と <code>reported_elapsed_ns</code> は診断値であり、 <code>compile-only</code>、<code>fail</code>、<code>unreported</code>、<code>invalid</code> の full-test 性能として 扱ってはいけません。</p><p>Celox については、ログ中に timing 行と result 行がそれぞれちょうど 1 個必要です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CELOX_TEST_TIMING test=&lt;requested-test&gt; compile_ns=&lt;integer&gt; execute_ns=&lt;integer&gt; jit_execute_ns=&lt;integer-or-NA&gt;</span></span>
<span class="line"><span>CELOX_TEST_RESULT test=&lt;requested-test&gt; status=pass|fail|compile-only elapsed_ns=&lt;integer&gt;</span></span></code></pre></div><p><code>veryl-cc-sync</code> は対応する <code>VERYL_TEST_TIMING</code> と <code>VERYL_TEST_RESULT</code> を 出力します。Celox の compile-only 結果は <code>execute_ns=0</code> でなければならず、 分離区間の合計は runner 内部の総時間を超えてはなりません。</p><p>形式不正、重複、欠落、test 名の不一致、compile-only mode との不一致、 process 終了 status との不一致は pass になりません。 <code>HELIODOR_CELOX_COMPILE_ONLY=1</code> が正常終了しても、<code>semantic_status</code> は <code>compile-only</code>、<code>elapsed_ns</code> は <code>NA</code> です。</p><p>既存の5列・9列・11列TSVは次回実行時にatomicに移行します。最初の内容を <code>results.tsv.v1.bak</code>、<code>results.tsv.v2.bak</code>、または<code>results.tsv.v3.bak</code>に保存し、参照先 log から 分離時間を復元できる場合は復元し、取得できない値は <code>NA</code> にします。process の 終了 status が 0 という事実だけで Celox full pass に昇格させることはありません。</p><p>parser/migration と acceptance gate の fixture は、Heliodor や compiler を checkout・実行せずにテストできます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests/run-heliodor-bench-results.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests/run-heliodor-bench-gate.sh</span></span></code></pre></div><h2 id="ciとdashboard" tabindex="-1">CIとdashboard <a class="header-anchor" href="#ciとdashboard" aria-label="Permalink to &quot;CIとdashboard&quot;">​</a></h2><p><code>.github/workflows/heliodor-bench.yml</code>は、関連するpull request、<code>master</code>へのpush、 manual dispatchで固定Linux workloadを実行します。semantic checkとVeryl比較は常に 必須です。pull requestでは、生成JIT実行時間が公開済みbaselineより10%を超えて悪化すると <code>github-action-benchmark</code>がjobを失敗させます。<code>master</code>ではCeloxのJIT実行、外側の post-codegen実行、compile時間、およびVerylの対応値を <a href="/celox/ja/benchmarks/">benchmark dashboard</a>の<strong>Heliodor Linux</strong> tabへ公開します。 正確なTSVとlogはworkflow artifactにも保存します。</p><h2 id="architectural-completion-marker" tabindex="-1">Architectural completion marker <a class="header-anchor" href="#architectural-completion-marker" aria-label="Permalink to &quot;Architectural completion marker&quot;">​</a></h2><p>Celox の testbench runner は Heliodor の <code>$display</code> を転送するため、Celox と Veryl の両ログに simulated cycle、architectural result register、pass bit が 残ります。固定 gate は process exit や test-result record とは独立に <code>cy=9ae070 x3=aa pass=1</code> を検査します。この検査は必須です。以前の native ISel 幅バグは <code>pass=1</code> のまま power-down しましたが、cycle は <code>9ab960</code> でした。</p>`,51)])])}const b=t(a,[["render",c]]);export{u as __pageData,b as default};
